# Import the necessary libraries
from typing import List
from collections import deque

# Define a TreeNode class to represent a binary tree node
class TreeNode:
    def __init__(self, val: int):
        self.val = val
        self.left = None
        self.right = None

# Function to find the largest value in each level of a binary tree
def largestValues(root: TreeNode) -> List[int]:
    """
    Find the largest value in each level of a binary tree.

    Args:
        root (TreeNode): The root node of the binary tree.

    Returns:
        List[int]: A list of integers containing the largest value in each level of the binary tree.
    """
    if not root:
        return []

    queue = deque()
    queue.append(root)

    levels = []
    while queue:
        level_size = len(queue)
        max_val = float('-inf')
        for _ in range(level_size):
            node = queue.popleft()
            max_val = max(max_val, node.val)

            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

        levels.append(max_val)

    return levels

# Function to perform level order traversal of a binary tree
def levelOrder(root: TreeNode) -> List[List[int]]:
    """
    Perform level order traversal of a binary tree.

    Args:
        root (TreeNode): The root node of the binary tree.

    Returns:
        List[List[int]]: A list of lists containing the values in each level of the binary tree.
    """
    if not root:
        return []

    queue = deque()
    queue.append(root)

    levels = []
    while queue:
        level = []
        level_size = len(queue)
        for _ in range(level_size):
            node = queue.popleft()
            level.append(node.val)

            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

        levels.append(level)

    return levels

# Example usage
root = TreeNode(3)
root.left = TreeNode(9)
root.right = TreeNode(20)
root.right.left = TreeNode(15)
root.right.right = TreeNode(7)

largestValuesResult = largestValues(root)
print("Largest values in each level:", largestValuesResult)

levelOrderResult = levelOrder(root)
print("Level order traversal:")
for level in levelOrderResult:
