struct Solution {
    fn subtreeWithAllDeepest(root: Option<TreeNode>) -> Option<TreeNode> {
        if root.is_none() {
            return None;
        }
        let mut depth = 0;
        let mut node = root;
        while let Some(node) = node {
            if node.left.is_none() && node.right.is_none() {
                return Some(node);
            }
            depth += 1;
            node = node.left.as_ref().unwrap_or(&TreeNode::new(0));
        }
        None
    }
}
