fn sum_of_left_leaves(root: Option<Box<TreeNode>>) -> i32 {
    if let Some(node) = root {
        if node.left.is_none() && node.right.is_none() {
            return node.val;
        }
        return sum_of_left_leaves(node.left) + sum_of_left_leaves(node.right);
    }
    0
}

// Function to check if a path from the root to a leaf node sums up to a given target.
fn has_path_sum(root: Option<Box<TreeNode>>, target_sum: i32) -> bool {
    if let Some(node) = root {
        if node.left.is_none() && node.right.is_none() && node.val == target_sum {
            return true;
        }
        return has_path_sum(node.left, target_sum - node.val) || has_path_sum(node.right, target_sum - node.val);
    }
    false
}

