from collections import defaultdict

def sumOfDistancesInTree(n, edges):
    tree = defaultdict(set)
    for u, v in edges:
        tree[u].add(v)
        tree[v].add(u)

    count = [1] * n
    res = [0] * n

    def dfs(node, parent):
        for child in tree[node]:
            if child != parent:
                dfs(child, node)
                count[node] += count[child]
                res[node] += res[child] + count[child]

    def dfs2(node, parent):
        for child in tree[node]:
            if child != parent:
                res[child] = res[node] - count[child] + n - count[child]
                dfs2(child, node)

    dfs(0, -1)
    dfs2(0, -1)

    # New function to calculate the sum of distances from the root to each node
    def sumOfDistances(node):
        if not tree[node]:
            return 0
        return count[node] + sumOfDistancesInTree(node, tree[node])

    return res

