    if (p == nullptr || q == nullptr) {
        return false;
    }
    if (p->val != q->val) {
        return false;
    }
    return isSameTree(p->left, q->left) && isSameTree(p->right, q->right);
}

bool isAncestor(TreeNode* root, int x) {
    if (root->val == x) {
        return true;
    }
    if (root->left != nullptr && isAncestor(root->left, x)) {
        return true;
    }
    if (root->right != nullptr && isAncestor(root->right, x)) {
        return true;
    }
    return false;
}

bool isCousins(TreeNode* root, int x, int y) {
    if (isAncestor(root, x) && isAncestor(root, y) && root->left != nullptr && root->right != nullptr) {
        return isAncestor(root->left, x) != isAncestor(root->right, x) && isAncestor(root->left, y) != isAncestor(root->right, y);
    }
    return false;
}

