struct TreeNode* buildTree(int* preorder, int* inorder, int preorderSize, int inorderSize) {
    // Base case: If preorder and inorder are empty, return NULL
    if (preorderSize == 0 || inorderSize == 0) {
        return NULL;
    }

    // Get the root value from preorder
    int root = preorder[0];

    // Create a new node with the root value
    struct TreeNode* rootNode = (struct TreeNode*) malloc(sizeof(struct TreeNode));
    rootNode->val = root;
    rootNode->left = NULL;
    rootNode->right = NULL;

    // Find the index of the root in the inorder traversal
    int inorderIndex = 0;
    for (int i = 0; i < inorderSize; i++) {
        if (inorder[i] == root) {
            inorderIndex = i;
            break;
        }
    }

    // Recursively build the left and right subtrees
    int leftPreorderSize = preorderSize - 1;
    int leftInorderSize = inorderIndex - 1;
    struct TreeNode* leftTree = buildTree(&preorder[1], inorder, leftPreorderSize, leftInorderSize);
    int rightPreorderSize = preorderSize - leftPreorderSize - 1;
    int rightInorderSize = inorderSize - leftInorderSize - 1;
    struct TreeNode* rightTree = buildTree(&preorder[leftPreorderSize + 1], inorder + leftInorderSize + 1, rightPreorderSize, rightInorderSize);

    // Set the left and right children of the root node
    rootNode->left = leftTree;
    rootNode->right = rightTree;

    return rootNode;
}

