def isValidPreorder(preorder: List[int]) -> bool:
    stack = []
    lower_bound = float('-inf')
    for num in preorder:
        if num < lower_bound:
            return False
        while stack and num > stack[-1]:
            lower_bound = stack.pop()
        stack.append(num)
    return True

def createBinaryTree(preorder: List[int]) -> TreeNode:
    stack = []
    lower_bound = float('-inf')
    for num in preorder:
        if num < lower_bound:
            return None
        while stack and num > stack[-1]:
            lower_bound = stack.pop()
        node = TreeNode(num)
        node.left = createBinaryTree(stack)
        stack.append(node)
    return stack[-1]
