from typing import List

def maxPoints(grid: List[List[int]], queries: List[int]) -> List[int]:
    m, n = len(grid), len(grid[0])
    dx = [-1, 0, 1, 0]
    dy = [0, 1, 0, -1]

    def dfs(x: int, y: int, q: int, visited: set) -> int:
        if 0 <= x < m and 0 <= y < n and grid[x][y] < q and (x, y) not in visited:
            visited.add((x, y))
            points = 1
            for i in range(4):
                nx, ny = x + dx[i], y + dy[i]
                points += dfs(nx, ny, q, visited)
            return points
        return 0

    def new_function(grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dx = [-1, 0, 1, 0]
        dy = [0, 1, 0, -1]
        visited = set()
        points = 0
        for i in range(m):
            for j in range(n):
                if (i, j) not in visited and grid[i][j] == 0:
                    visited.add((i, j))
                    points += 1
                    for k in range(4):
                        ni, nj = i + dx[k], j + dy[k]
                        if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 0:
                            points += new_function(grid)
        return points

    return [dfs(0, 0, query, set()) for query in queries] + [new_function(grid)]
