int countIslands(vector<vector<int>>& grid) {
    int count = 0;

    for (int row = 0; row < grid.size(); row++) {
        for (int col = 0; col < grid[0].size(); col++) {
            if (grid[row][col] == 1) {
                grid[row][col] = 0;
                count++;
                grid[row][col] = 1;
            }
