        for i in range(len(maze)):
            for j in range(len(maze[0])):
                if maze[i][j] == 1 and (i-1, j) != start and (i+1, j) != start and (i, j-1) != start and (i, j+1) != start:
                    maze[i][j] = 0
                    if find_path(maze, (i, j), destination):
