#include <stdio.h>

// Function to count the number of pseudo-palindromic paths in a binary tree
int pseudoPalindromicPaths(TreeNode* root) {
    if (!root) return 0;
    int cnt = 1 << (root->val - 1);
    if (!root->left && !root->right) {
        return (cnt & (cnt - 1)) == 0;
    }
    return pseudoPalindromicPaths(root->left) + pseudoPalindromicPaths(root->right);
}

