    if (!root) return 0;
    int cnt = 1 << (root->val - 1);
    if (!root->left && !root->right) {
        return (cnt & (cnt - 1)) == 0;
    }
    return pseudoPalindromicPaths(root->left) + pseudoPalindromicPaths(root->right);
}
