use SplStack;

class Solution
{
    /**
     * @param equations: A list of strings
     * @param values: A list of integers
     * @param queries: A list of strings
     * @return: A list of integers
     */
    function calcEquation($equations, $values, $queries): array
    {
        $graph = [];
        for ($i = 0; $i < count($equations); $i++) {
            $graph[$equations[$i][0]] = [$equations[$i][1] => $values[$i]];
            $graph[$equations[$i][1]] = [$equations[$i][0] => 1 / $values[$i]];
        }

        $ans = [];
        foreach ($queries as $q) {
            if (!isset($graph[$q[0]]) || !isset($graph[$q[1]])) {
                $ans[] = -1.0;
            } else {
                $ans[] = $this->dfs($q[0], $q[1], $graph);
            }
        }
        return $ans;
    }

    function dfs($s1, $s2, $graph): float
    {
        if ($s1 === $s2) {
            return 1.0;
        }
        if (!isset($graph[$s1]) || !isset($graph[$s2])) {
            return -1.0;
        }

        $stack = new SplStack();
        $stack->push($s1);
        while (!$stack->isEmpty()) {
            $s = $stack->pop();
            foreach ($graph[$s] as $s3 => $value) {
                if ($this->dfs($s3, $s2, $graph) > 0) {
                    return $value * $this->dfs($s3, $s2, $graph);
                }
            }
        }
        return -1.0;
    }
