from typing import List

class Solution:
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        m = len(heights)
        n = len(heights[0])
        pacific = [[False] * n for _ in range(m)]
        atlantic = [[False] * n for _ in range(m)]

        for r in range(m):
            self.dfs(heights, r, 0, -1, pacific)
            self.dfs(heights, r, n - 1, -1, atlantic)

        for c in range(n):
            self.dfs(heights, 0, c, -1, pacific)
            self.dfs(heights, m - 1, c, -1, atlantic)

        result = []
        for r in range(m):
            for c in range(n):
                if pacific[r][c] and atlantic[r][c]:
                    result.append([r, c])

        return result

    def dfs(self, heights: List[List[int]], r: int, c: int, prevHeight: int, visited: List[List[bool]]) -> None:
        if r < 0 or r >= len(heights) or c < 0 or c >= len(heights[0]):
