int pseudoPalindromicPaths(TreeNode* root, int cnt = 0) {
    if (!root) return 0;
    cnt ^= 1 << (root->val - 1);
    if (!root->left && !root->right)
        return (cnt & (cnt - 1)) == 0; 
    return pseudoPalindromicPaths(root->left, cnt) + pseudoPalindromicPaths(root->right, cnt);
}

bool isPseudoPalindromic(TreeNode* root) {
    if (!root) return true;
    int cnt = 0;
    cnt ^= 1 << (root->val - 1);
    if (!root->left && !root->right)
        return (cnt & (cnt - 1)) == 0; 
    return isPseudoPalindromic(root->left) && isPseudoPalindromic(root->right);
}
