package main

import (
	"container/heap"
	"fmt"
)

type priorityQueue struct {
	items []int
}

func (pq *priorityQueue) Len() int { return len(pq.items) }
func (pq *priorityQueue) Less(i, j int) bool {
	return pq.items[i] < pq.items[j]
}
func (pq *priorityQueue) Swap(i, j int) {
	pq.items[i], pq.items[j] = pq.items[j], pq.items[i]
}
func (pq *priorityQueue) Push(x interface{}) {
	pq.items = append(pq.items, x.(int))
}
func (pq *priorityQueue) Pop() interface{} {
	old := pq.items
	n := len(old)
	pq.items = old[:n-1]
	return pq.items[n-1]
}

func goodSubarrays(nums []int, k int) int {
	pq := &priorityQueue{}
	for _, num := range nums {
		heap.Push(pq, num)
	}
	count := 0
	for i := 0; i < len(nums); i++ {
		num := heap.Pop(pq).(int)
		if i < k-1 {
			heap.Push(pq, num)
		} else {
			count++
		}
	}
	return count
}

func newFunction(nums []int, k int) int {
	pq := &priorityQueue{}
	for _, num := range nums {
		heap.Push(pq, num)
	}
	count := 0
	for i := 0; i < len(nums); i++ {
		num := heap.Pop(pq).(int)
		if i < k-1 {
			heap.Push(pq, num)
		} else {
			count++
		}
	}
	return count
}

func main() {
	nums := []int{1, 1, 2, 3, 4, 5, 6}
	k := 4
	fmt.Println(goodSubarrays(nums, k))
	fmt.Println(newFunction(nums, k))
}
