public class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        HashSet<String> dict = new HashSet<>(wordDict);
        HashMap<String, List<String>> memo = new HashMap<>();
        return helper(s, dict, memo);
    }

    private List<String> helper(String s, HashSet<String> dict, HashMap<String, List<String>> memo) {
        if (memo.containsKey(s)) {
            return memo.get(s);
        }

        List<String> res = new ArrayList<>();
        if (dict.contains(s)) {
            res.add(s);
        }

        for (int i = 1; i < s.length(); ++i) {
            String prefix = s.substring(0, i);
            if (!dict.contains(prefix)) continue;
            String suffix = s.substring(i);
            List<String> temp = helper(suffix, dict, memo);
            for (String t : temp) {
                res.add(prefix + " " + t);
            }
        }

        memo.put(s, res);
        return res;
    }

    // New function to handle the new requirement
    public List<String> wordBreak2(String s, List<String> words) {
        HashMap<String, List<String>> memo = new HashMap<>();
        return helper2(s, words, memo);
    }

    private List<String> helper2(String s, List<String> words, HashMap<String, List<String>> memo) {
        if (memo.containsKey(s)) {
            return memo.get(s);
        }

        List<String> res = new ArrayList<>();
        for (String word : words) {
            if (s.startsWith(word)) {
                res.add(word);
                String suffix = s.substring(word.length());
                List<String> temp = helper2(suffix, words, memo);
                for (String t : temp) {
                    res.add(word + " " + t);
                }
            }
        }

        memo.put(s, res);
        return res;
    }
}
