public List<List<Integer>> findSubstring(String s, List<String> words) {
    List<List<Integer>> result = new ArrayList<>();
    int n = s.length();
    int m = words.size();
    int k = words.get(0).length();

    // Create a hash map to store the counts of each word
    Map<String, Integer> wordCount = new HashMap<>();
    for (String word : words) {
        wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
    }

    // Find all substrings of length k in s
    for (int i = 0; i <= n - k * m; i++) {
        String substring = s.substring(i, i + k * m);
        Map<String, Integer> substringCount = new HashMap<>(wordCount);

        // Check if the substring matches the word count
        for (int j = 0; j < m; j++) {
            String word = substring.substring(j * k, (j + 1) * k);
            if (substringCount.containsKey(word)) {
                substringCount.put(word, substringCount.get(word) - 1);
                if (substringCount.get(word) == 0) {
                    substringCount.remove(word);
                }
            } else {
                break;
            }
        }

        // If the substring matches the word count, add it to the result
        if (substringCount.isEmpty()) {
            result.add(Arrays.asList(i, i + k * m - 1));
        }
    }

    return result;
}
