from typing import List

def eventualSafeNodes(graph: List[List[int]]) -> List[int]:
    n = len(graph)
    color = [0] * n
    ans = []

    def hasCycle(node: int, color: List[int], graph: List[List[int]]) -> bool:
        if color[node] > 0:
            return color[node] == 1
        color[node] = 1
        for neighbor in graph[node]:
            if hasCycle(neighbor, color, graph):
                return True
        color[node] = 2
        return False

    def findPuzzle(words: List[str], puzzles: List[str]) -> List[int]:
        for i in range(len(words)):
            for j in range(len(puzzles)):
                if words[i] == puzzles[j]:
                    return [i, j]
        return [-1, -1]

    for i in range(n):
        if not hasCycle(i, color, graph):
            ans.append(i)
    return ans

