    std::unordered_set<std::string> s(nums.begin(), nums.end());
    int n = nums.size();

    for (int i = 0; i < (1 << n); ++i) {
        std::string candidate(n, '0');
        for (int j = 0; j < n; ++j) {
            if (i & (1 << j))
                candidate[j] = '1';
        }

        if (s.find(candidate) == s.end()) {
            return candidate;
        }
    }
    return "";
}

