    std::vector<std::string> result;
    std::string word = "";
    for (char c : s) {
        if (c == ' ') {
            if (word.size() > 0) {
                result.push_back(word);
            }
            word = "";
        } else {
            word += c;
        }
    }
    if (word.size() > 0) {
        result.push_back(word);
    }

    for (const auto& word : wordDict) {
        if (std::find(result.begin(), result.end(), word) == result.end()) {
            result.push_back(word);
        }
    }

    return result;
