package main

import (
	"container/heap"
	"fmt"
	"sort"
)

type Pair struct {
	value int
	count int
}

type MinHeap []Pair

func (h MinHeap) Len() int           { return len(h) }
func (h MinHeap) Less(i, j int) bool { return h[i].count < h[j].count }
func (h MinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *MinHeap) Push(x interface{}) {
	*h = append(*h, x.(Pair))
}
func (h *MinHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

func kMostFrequent(nums []int, k int) []int {
	freq := make(map[int]int)
	for _, num := range nums {
		freq[num]++
	}
	heap.Init(&MinHeap{make([]Pair, len(freq))})
	for _, num := range freq {
		heap.Push(&MinHeap{make([]Pair, len(freq))}, Pair{num, num})
		if heap.Len() > k {
			heap.Pop(&MinHeap{make([]Pair, len(freq))})
		}
	}
	result := make([]int, 0, k)
	for i := 0; i < k; i++ {
		result = append(result, heap.Pop(&MinHeap{make([]Pair, len(freq))}).(Pair).value)
	}
	return result
}

