from bisect import bisect

def maxSizeSubsequenceSumQueries(nums, queries):
    nums.sort()
    prefixSums = [0] * (len(nums) + 1)
    for i, x in enumerate(nums):
        prefixSums[i + 1] = prefixSums[i] + x

    answer = []
    for q in queries:
        idx = bisect(prefixSums, q)
        answer.append(idx - 1)

    # New function to find the maximum sum of a subsequence
    def maxSubsequenceSum(nums):
        nums.sort()
        prefixSums = [0] * (len(nums) + 1)
        for i, x in enumerate(nums):
            prefixSums[i + 1] = prefixSums[i] + x

        maxSum = 0
        for i in range(len(nums)):
            if prefixSums[i + 1] - prefixSums[i] > maxSum:
                maxSum = prefixSums[i + 1] - prefixSums[i]

        return maxSum

    return answer, maxSubsequenceSum(nums)
