def count_fair_pairs(nums, lower, upper):
    n = len(nums)
    fair_pairs = 0
    for i in range(n):
        for j in range(i+1, n):
            if lower <= nums[i] + nums[j] <= upper:
                fair_pairs += 1
    return fair_pairs

