#include <string>
#include <iostream>

int countHomogenous(std::string s) {
    int res = 0, count = 1, mod = 1e9 + 7;
    for (int i = 1; i < s.size(); ++i) {
        count = (s[i] == s[i - 1]) ? count + 1 : 1;
        res = (res + count) % mod;
    }
    return res;
}

int countHomogenousRange(std::string s, int lower, int upper) {
    int res = 0, count = 1, mod = 1e9 + 7;
    for (int i = lower; i <= upper; ++i) {
        count = (s[i] == s[i - 1]) ? count + 1 : 1;
        res = (res + count) % mod;
    }
    return res;
}

