import java.util.*
import kotlin.collections.*

fun kMostFrequent(nums: IntArray, k: Int): IntArray {
    val frequency = HashMap<Int, Int>()
    for (num in nums) {
        frequency[num] = (frequency[num] ?: 0) + 1
    }

    val minHeap = PriorityQueue<Pair<Int, Int>, Pair<Int, Int>>(Comparator.comparing { it.first }.reversed())
    for ((_, count) in frequency) {
        minHeap.add(Pair(count, num))
        if (minHeap.size > k) {
            minHeap.poll()
        }
    }

    val result = mutableListOf<Int>()
    while (!minHeap.isEmpty()) {
        result.add(minHeap.poll().second)
    }
    return result.toIntArray()
}

