use std::collections::HashMap;
use std::collections::BinaryHeap;
use std::cmp::Reverse;

fn k_most_frequent(nums: &Vec<i32>, k: i32) -> Vec<i32> {
    let mut frequency = HashMap::<i32, i32>::new();
    for &num in nums {
        *frequency.entry(num).or_insert(0) += 1;
    }

    let mut min_heap = BinaryHeap::new();
    for &(count, _) in frequency {
        min_heap.push(Reverse((count, num)));
        if min_heap.len() > k as usize {
            min_heap.pop();
        }
    }

    let mut result = Vec::new();
    while let Some(Reverse((count, num))) = min_heap.next() {
        result.push(num);
    }
    result
}

