import java.util.*;
import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int[] kMostFrequent(int[] nums, int k) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int num : nums) {
            frequency.put(num, frequency.getOrDefault(num, 0) + 1);
        }

        PriorityQueue<Pair<Integer, Integer>> minHeap = new PriorityQueue<>(Comparator.comparingInt(pair -> pair.first));
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            minHeap.add(new Pair<>(entry.getValue(), entry.getKey()));
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }

        int[] result = new int[k];
        int index = 0;
        while (!minHeap.isEmpty()) {
            result[index++] = minHeap.poll().second;
        }
        return result;
    }

    public List<String> topKFrequentWords(List<String> words, int k) {
        Map<String, Integer> frequency = new HashMap<>();
        for (String word : words) {
            frequency.put(word, frequency.getOrDefault(word, 0) + 1);
        }

        PriorityQueue<Pair<Integer, String>> minHeap = new PriorityQueue<>(Comparator.comparingInt(pair -> pair.first));
        for (Map.Entry<String, Integer> entry : frequency.entrySet()) {
            minHeap.add(new Pair<>(entry.getValue(), entry.getKey()));
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }

        List<String> result = new ArrayList<>();
        while (!minHeap.isEmpty()) {
            result.add(minHeap.poll().second);
        }
        return result;
    }
}
