using System.Collections;
using System.Collections.Generic;
using System;

public class Solution {
    public int[] KMostFrequent(int[] nums, int k) {
        Dictionary<int, int> frequency = new Dictionary<int, int>();
        foreach (int num in nums) {
            frequency[num] = frequency.ContainsKey(num) ? frequency[num] + 1 : 1;
        }

        PriorityQueue<KeyValuePair<int, int>> minHeap = new PriorityQueue<KeyValuePair<int, int>>(Comparer<KeyValuePair<int, int>>.Create((x, y) => x.Key.CompareTo(y.Key)));
        foreach (KeyValuePair<int, int> entry in frequency) {
            minHeap.Enqueue(entry, entry.Value);
            if (minHeap.Count > k) {
                minHeap.Dequeue();
            }
        }

        int[] result = new int[k];
        int index = 0;
        while (minHeap.Count > 0) {
            KeyValuePair<int, int> pair = minHeap.Dequeue();
            result[index++] = pair.Key;
        }
        return result;
    }

    public List<string> TopKFrequentWords(List<string> words, int k) {
        Dictionary<string, int> frequency = new Dictionary<string, int>();
        foreach (string word in words) {
            frequency[word] = frequency.ContainsKey(word) ? frequency[word] + 1 : 1;
        }

        PriorityQueue<KeyValuePair<int, string>> minHeap = new PriorityQueue<KeyValuePair<int, string>>(Comparer<KeyValuePair<int, string>>.Create((x, y) => x.Key.CompareTo(y.Key)));
        foreach (KeyValuePair<string, int> entry in frequency) {
            minHeap.Enqueue(entry, entry.Value);
            if (minHeap.Count > k) {
                minHeap.Dequeue();
            }
        }

        List<string> result = new List<string>();
        while (minHeap.Count > 0) {
            KeyValuePair<int, string> pair = minHeap.Dequeue();
            result.Add(pair.Key);
        }
        return result;
    }
}
