package main

import (
	"container/heap"
	"fmt"
	"sort"
)

type Pair struct {
	count int
	num   int
}

type PriorityQueue []*Pair

func (pq PriorityQueue) Len() int           { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool { return pq[i].count > pq[j].count }
func (pq PriorityQueue) Swap(i, j int)      { pq[i], pq[j] = pq[j], pq[i] }
func (pq *PriorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(*Pair))
}
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	x := old[n-1]
	*pq = old[0 : n-1]
	return x
}

func kMostFrequent(nums []int, k int) []int {
	frequency := make(map[int]int)
	for _, num := range nums {
		frequency[num]++
	}
	pq := make(PriorityQueue, 0, len(frequency))
	for _, count := range frequency {
		heap.Push(&pq, &Pair{count, num})
		if len(pq) > k {
			heap.Pop(&pq)
		}
	}
	result := make([]int, k)
	for i := 0; i < k; i++ {
		result[i] = pq[i].num
	}
	return result
}

func topKFrequentWords(words []string, k int) []string {
	frequency := make(map[string]int)
	for _, word := range words {
		frequency[word]++
	}
	pq := make(PriorityQueue, 0, len(frequency))
	for _, count := range frequency {
		heap.Push(&pq, &Pair{count, word})
		if len(pq) > k {
			heap.Pop(&pq)
		}
	}
	result := make([]string, k)
	for i := 0; i < k; i++ {
		result[i] = pq[i].word
	}
	return result
}

func main() {
	nums := []int{1, 1, 1, 2, 2, 3}
	k := 2
	fmt.Println(kMostFrequent(nums, k))
}
