import java.util.*;
import java.util.function.Function;

public class Solution {
    public String sortByFrequency(String s) {
        // Using a HashMap to store character frequencies
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : s.toCharArray()) {
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        // Sorting the characters based on their frequency
        List<Character> sortedChars = new ArrayList<>(freq.keySet());
        sortedChars.sort((a, b) -> freq.get(a) - freq.get(b));

        return new String(sortedChars.toArray());
    }

    public List<Integer> topKFrequent(int[] nums, int k) {
        // Using a HashMap to store integer frequencies
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        // Creating a priority queue to store the top k frequent integers
        PriorityQueue<Integer> pq = new PriorityQueue<>(k, (a, b) -> freq.get(a) - freq.get(b));
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            pq.add(entry.getKey());
            if (pq.size() > k) {
                pq.poll();
            }
        }

        List<Integer> result = new ArrayList<>();
        while (!pq.isEmpty()) {
            result.add(pq.poll());
        }
        return result;
    }
}
