class Solution {
    fun sortByFrequency(s: String): String {
        // Using a HashMap to store character frequencies
        val freq = HashMap<Char, Int>()
        for (c in s.toCharArray()) {
            freq[c] = freq.getOrDefault(c, 0) + 1
        }

        // Sorting the characters based on their frequency
        val sortedChars = freq.keys.sortedBy { freq[it] }

        return String(sortedChars)
    }

    fun topKFrequent(nums: IntArray, k: Int): List<Int> {
        // Using a HashMap to store integer frequencies
        val freq = HashMap<Int, Int>()
        for (num in nums) {
            freq[num] = freq.getOrDefault(num, 0) + 1
        }

        // Creating a priority queue to store the top k frequent integers
        val pq = PriorityQueue(k, compareBy { freq[it] })
        for (entry in freq.entries) {
            pq.add(entry.key)
            if (pq.size > k) {
                pq.poll()
            }
        }

        val result = mutableListOf<Int>()
        while (!pq.isEmpty()) {
            result.add(pq.poll())
        }
        return result
    }
}
