from collections import defaultdict


def largestPathValue(colors, edges):
    def dfs(node):
        if not cache[node][ord(colors[node]) - ord('a')]:
            cache[node][ord(colors[node]) - ord('a')] = 1
            for neighbor in graph[node]:
                cache[node][ord(colors[node]) - ord('a')] = max(cache[node][ord(colors[node]) - ord('a')],
                                                               1 + dfs(neighbor))
        return cache[node][ord(colors[node]) - ord('a')]

    n = len(colors)
    graph = [set() for _ in range(n)]
    for a, b in edges:
        graph[a].add(b)

    cache = [[0] * 26 for _ in range(n)]
    in_degree = [0] * n
    for a, b in edges:
        in_degree[b] += 1
    res = -1
    for i in range(n):
        if in_degree[i] == 0:
            res = max(res, dfs(i))
    return res


def req_skills_to_people(req_skills):
    people = []
    for skill in req_skills:
        people.append([skill])
    return people


def people_to_req_skills(people):
    req_skills = []
    for person in people:
        req_skills.extend(person)
    return list(set(req_skills))


def main():
    tasks = \[1,2,3\]
    sessionTime = 3
    colors = \["java","nodejs","reactjs"\]
    edges = \[(1,2),(2,3),(3,1)\]
    print(largestPathValue(colors, edges))
    req_skills = \["java","nodejs","reactjs"\]
    people = \[\["java"\],\["nodejs"\],\["nodejs","reactjs"\]\]
    print(req_skills_to_people(req_skills))
    print(people_to_req_skills(people))


if __name__ == "__main__":
    main()
