import queue
from typing import List

def shortestPathLength(graph: List[List[int]]) -> int:
    n = len(graph)
    q = queue.Queue()
    for i in range(n):
        q.put((i, 1 << i))
    steps = -1
    visited = [[False] * (1 << n) for _ in range(n)]

    while not q.empty():
        steps += 1
        size = q.qsize()

        for k in range(size):
            currNode, currVisits = q.get()
            if currVisits == (1 << n) - 1: return steps
            for nextNode in graph[currNode]:
                nextVisits = currVisits
                nextVisits |= 1 << nextNode
                if not visited[nextNode][nextVisits]:
                    visited[nextNode][nextVisits] = True
                    q.put((nextNode, nextVisits))
    return -1

def longestPathLength(values: List[int]) -> int:
    n = len(values)
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if values[i] == values[j]:
                graph[i].append(j)
    return shortestPathLength(graph)
